from numpy import *

t = array([int]*20)

def Saisie():
    b = False
    while not(b) :
        n=int(input("Donnerle nombre de cases : "))
        b = 5 <= n <= 25
    return n

def Remplir(n):
    t[0]=int(input("t["+str(0)+"]= "))
    for i in range(1,n):
        b = False
        while not(b):
            t[i]=int(input("t["+str(i)+"]= "))
            b = t[i] > t[i-1]
            
def Afficher(t,n):
    for i in range (n):
        print(t[i],end="/")
        
#########################PP############################"
n= Saisie()
